INSERT INTO "roles" ("id", "name", "description", "created_at", "updated_at")
SELECT v.id::uuid, v.name, v.description, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM (
  VALUES
  ('22222222-2222-2222-2222-222222220002', 'super_admin', 'Full system access to all features and data. This role is intended for platform administrators.'),
  ('22222222-2222-2222-2222-222222220001', 'admin', 'Manage platform operations'),
  ('22222222-2222-2222-2222-222222220003', 'customer_support', 'Customer service and support'),
  ('22222222-2222-2222-2222-222222220004', 'inventory_manager', 'Inventory and warehouse'),
  ('22222222-2222-2222-2222-222222220005', 'marketing_manager', 'Promotions and campaigns'),
  ('22222222-2222-2222-2222-222222220006', 'analyst', 'Analytics and reporting')
) AS v(id, name, description)
WHERE NOT EXISTS (SELECT 1 FROM "roles" r WHERE r."name" = v.name);

UPDATE "roles" AS r
SET
  "description" = v.description,
  "updated_at" = CURRENT_TIMESTAMP
FROM (
  VALUES
  ('22222222-2222-2222-2222-222222220002', 'super_admin', 'Full system access to all features and data. This role is intended for platform administrators.'),
  ('22222222-2222-2222-2222-222222220001', 'admin', 'Manage platform operations'),
  ('22222222-2222-2222-2222-222222220003', 'customer_support', 'Customer service and support'),
  ('22222222-2222-2222-2222-222222220004', 'inventory_manager', 'Inventory and warehouse'),
  ('22222222-2222-2222-2222-222222220005', 'marketing_manager', 'Promotions and campaigns'),
  ('22222222-2222-2222-2222-222222220006', 'analyst', 'Analytics and reporting')
) AS v(id, name, description)
WHERE r."name" = v.name
  AND (r."description" IS DISTINCT FROM v.description);

